with s(r) as (
select concat_ws(' ','con',conrelid::regclass,contypid::regtype,conname,contype,condeferrable,condeferred,convalidated,conkey,confkey,confrelid::regclass,confupdtype,confdeltype,confmatchtype,conislocal,connoinherit,md5(regexp_replace(regexp_replace(coalesce(conbin::text,''),':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g'))) from pg_constraint where connamespace='public'::regnamespace
union all select concat_ws(' ','def',adrelid::regclass,adnum,md5(regexp_replace(regexp_replace(adbin::text,':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g'))) from pg_attrdef a join pg_class c on c.oid=a.adrelid where c.relnamespace='public'::regnamespace
union all select concat_ws(' ','idx',indexrelid::regclass,indrelid::regclass,md5(regexp_replace(regexp_replace(coalesce(indexprs::text,'')||coalesce(indpred::text,''),':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g')),indkey::text,(select string_agg(opcname,',' order by ord) from unnest(indclass) with ordinality u(o,ord) join pg_opclass oc on oc.oid=u.o),(select string_agg(coalesce(collname,'-'),',' order by ord) from unnest(indcollation) with ordinality u(o,ord) left join pg_collation co on co.oid=u.o),indoption::text,indisunique,indnullsnotdistinct,indimmediate,indisprimary,indisexclusion,indisvalid,indnkeyatts) from pg_index i join pg_class c on c.oid=i.indexrelid where c.relnamespace='public'::regnamespace
union all select concat_ws(' ','trg',tgrelid::regclass,tgname,tgtype,tgenabled,tgfoid::regprocedure,md5(regexp_replace(regexp_replace(coalesce(tgqual::text,''),':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g')),encode(tgargs,'hex'),tgattr::text,tgdeferrable,tginitdeferred,tgoldtable,tgnewtable,tgconstraint<>0) from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and not tgisinternal
union all select concat_ws(' ','fn',p.oid::regprocedure,md5(prosrc),md5(regexp_replace(regexp_replace(coalesce(prosqlbody::text,''),':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g')),provolatile,prosecdef,proleakproof,proisstrict,proparallel,prokind,proretset,procost,prorows,proconfig::text,prorettype::regtype,proargnames::text,proargmodes::text,prolang::regproc::text,(select lanname from pg_language l where l.oid=p.prolang),md5(coalesce(proargdefaults::text,'')),proacl::text,obj_description(p.oid,'pg_proc')) from pg_proc p where pronamespace='public'::regnamespace and not exists(select 1 from pg_depend d where d.objid=p.oid and d.classid='pg_proc'::regclass and d.deptype='e')
union all select concat_ws(' ','rel',c.oid::regclass,relkind,relpersistence,relreplident,relrowsecurity,relforcerowsecurity,relispartition,reloptions::text,relacl::text,reltype<>0,relam,(select string_agg(i.inhparent::regclass::text,',') from pg_inherits i where i.inhrelid=c.oid),pg_get_partkeydef(c.oid),obj_description(c.oid,'pg_class')) from pg_class c where relnamespace='public'::regnamespace and not exists(select 1 from pg_depend d where d.objid=c.oid and d.classid='pg_class'::regclass and d.deptype='e')
union all select concat_ws(' ','att',attrelid::regclass,attnum,attname,atttypid::regtype,atttypmod,attnotnull,attstorage,attcompression,attcollation::regcollation,attoptions::text,attidentity,attgenerated,attisdropped,attstattarget,attacl::text,col_description(attrelid,attnum)) from pg_attribute a join pg_class c on c.oid=a.attrelid where c.relnamespace='public'::regnamespace and attnum>0 and not exists(select 1 from pg_depend d where d.objid=c.oid and d.classid='pg_class'::regclass and d.deptype='e')
union all select concat_ws(' ','seq',seqrelid::regclass,seqtypid::regtype,seqstart,seqincrement,seqmax,seqmin,seqcache,seqcycle) from pg_sequence s join pg_class c on c.oid=s.seqrelid where c.relnamespace='public'::regnamespace
union all select concat_ws(' ','pol',polrelid::regclass,polname) from pg_policy
union all select concat_ws(' ','rule',ev_class::regclass,rulename,ev_type,is_instead,md5(regexp_replace(regexp_replace(ev_action::text,':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g')),md5(regexp_replace(regexp_replace(coalesce(ev_qual::text,''),':location -?[0-9]+','','g'),'\m(1[6-9][0-9]{3}|[2-9][0-9]{4}|[0-9]{6,})\M','OID','g'))) from pg_rewrite r join pg_class c on c.oid=r.ev_class where c.relnamespace='public'::regnamespace
union all select concat_ws(' ','typ',t.oid::regtype,typtype,typnotnull,typbasetype::regtype,typcollation) from pg_type t where typnamespace='public'::regnamespace and typtype<>'b' and not exists(select 1 from pg_depend d where d.objid=t.oid and d.classid='pg_type'::regclass and d.deptype='e')
union all select concat_ws(' ','stx',stxname) from pg_statistic_ext
union all select concat_ws(' ','evt',evtname) from pg_event_trigger
union all select concat_ws(' ','ns',nspname,nspacl::text) from pg_namespace
union all select concat_ws(' ','enum',enumtypid::regtype,enumsortorder,enumlabel) from pg_enum
union all select concat_ws(' ','ext',extname,extversion,extnamespace::regnamespace) from pg_extension
union all select concat_ws(' ','dbcfg',setrole,setconfig::text) from pg_db_role_setting where setdatabase=(select oid from pg_database where datname=current_database())
union all select concat_ws(' ','defacl',defaclrole::regrole,defaclnamespace,defaclobjtype,defaclacl::text) from pg_default_acl
union all select concat_ws(' ','dep-count',classid::regclass,refclassid::regclass,deptype,count(*)) from pg_depend where classid<>0 group by classid,refclassid,deptype
union all select concat_ws(' ','pub',pubname) from pg_publication
)
select r from s order by 1;
